1	// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
2	// Authoring builds as CODE: design one bay, tile it; mirror for symmetry; protect function with a guard.
3	// Coordinate bookkeeping is where design time and errors go — write a short generator script with these helpers
4	// instead of typing hundreds of coordinates.
5	//
6	//   import { load, Grid, guard, tile, mirrorX, B, face } from "<plugin>/tools/src/build.mjs"
7	//   const g = guard(load("in.nbt"))                 // refuses writes into functional cells (see check.mjs)
8	//   runParts(g, [["shell", shellPart], ["porch", porchPart]], { palette: "palette.json" })  // later parts only add
9	//   tile(g, { from: 1, step: 4, count: 5, axis: "z" }, (z) => bay(g, z))
10	//   g.save("out.nbt")
11	import { existsSync, readFileSync, writeFileSync } from "node:fs";
12	import { load, Grid, ns } from "./structure.mjs";
13	import { t } from "./nbt.mjs";
14	import { functionalCells } from "./check.mjs";
15	import { reroof } from "./roofs.mjs";
16	import { reservedCells, layoutSockets, socketFitout } from "./sockets.mjs";
17	export { load, Grid };
18	
19	// ---- directions -------------------------------------------------------------------------------------------------
20	export const DIRS = { north: [0, 0, -1], south: [0, 0, 1], west: [-1, 0, 0], east: [1, 0, 0] };
21	export const OPPOSITE = { north: "south", south: "north", east: "west", west: "east", up: "down", down: "up" };
22	const CW = { north: "east", east: "south", south: "west", west: "north" };
23	export const face = {
24	  opposite: (f) => OPPOSITE[f],
25	  cw: (f) => CW[f],
26	  ccw: (f) => OPPOSITE[CW[f]],
27	  /** Mirror a facing across the YZ plane (x -> -x) or XY plane (z -> -z). */
28	  mirrorX: (f) => (f === "east" ? "west" : f === "west" ? "east" : f),
29	  mirrorZ: (f) => (f === "north" ? "south" : f === "south" ? "north" : f),
30	};
31	
32	// ---- block helpers: return [block, state] pairs for g.set(x, y, z, ...B.stairs(...)) ----------------------------
33	// Stairs `facing` = the side of the full-height back; a cornice/bracket lip toward the street uses
34	// facing = the INWARD direction with half: "top".
35	export const B = {
36	  stairs: (mat, facing, half = "bottom", shape = "straight") => [`${mat}_stairs`, { facing, half, shape, waterlogged: "false" }],
37	  slab: (mat, type = "bottom") => [`${mat}_slab`, { type, waterlogged: "false" }],
38	  log: (mat, axis = "y") => [`${mat}_log`, { axis }],
39	  wood: (mat, axis = "y") => [`${mat}_wood`, { axis }],
40	  pillar: (block, axis = "y") => [block, { axis }],
41	  trapdoor: (mat, facing, half = "bottom", open = false) => [`${mat}_trapdoor`, { facing, half, open: String(open), powered: "false", waterlogged: "false" }],
42	  door: (mat, facing, half = "lower", hinge = "left") => [`${mat}_door`, { facing, half, hinge, open: "false", powered: "false" }],
43	  fence: (mat) => [`${mat}_fence`, {}],
44	  wall: (mat) => [`${mat}_wall`, {}],
45	  pane: (block = "glass_pane") => [block, {}],
46	  lantern: (hanging = false) => ["lantern", { hanging: String(hanging), waterlogged: "false" }],
47	  chain: (axis = "y", version26 = true) => [version26 ? "iron_chain" : "chain", { axis, waterlogged: "false" }],
48	  wallTorch: (facing) => ["wall_torch", { facing }],
49	  block: (name) => [name, {}],
50	  /**
51	   * A banner with patterns: [block, state, nbt] for g.set(x, y, z, ...B.banner(...)). patterns: [[pattern, colour], ...]
52	   * (ids such as stripe_center, border, cross, rhombus, flower, globe, gradient, half_horizontal, curly_border).
53	   * wall: hung on the block behind it, facing `facing`; standing: `rotation` 0..15 (0 faces south). legacy: the
54	   * pre-1.20.5 Patterns/Pattern/Color form (for 1.20.4 and older).
55	   */
56	  banner: (color, patterns = [], { wall = true, facing = "north", rotation = 0, legacy = false } = {}) => {
57	    const block = wall ? `${color}_wall_banner` : `${color}_banner`, state = wall ? { facing } : { rotation: String(rotation) };
58	    const pats = patterns.map((p) => (Array.isArray(p) ? { pattern: p[0], color: p[1] } : p));
59	    const nbt = legacy
60	      ? t.compound({ id: t.string("minecraft:banner"), Patterns: t.list("compound", pats.map((p) => ({ Pattern: t.string(LEGACY_PATTERN[p.pattern] ?? p.pattern), Color: t.int(DYE_INDEX.indexOf(p.color)) }))) })
61	      : t.compound({ id: t.string("minecraft:banner"), patterns: t.list("compound", pats.map((p) => ({ pattern: t.string(`minecraft:${p.pattern.replace(/^minecraft:/, "")}`), color: t.string(p.color) }))) });
62	    return [block, state, nbt];
63	  },
64	  /**
65	   * A sign with text: [block, state, nbt]. lines: up to 4 strings (front); back: up to 4 more. wood "oak", "spruce" ...
66	   * wall (facing) or standing (rotation 0..15); hanging: a hanging sign. color: dye name; glow: glowing text.
67	   * dataVersion: text is written as JSON components before 1.21.5 (4325) and as plain string components after.
68	   */
69	  sign: (wood = "oak", lines = [], { wall = true, facing = "north", rotation = 0, hanging = false, color = "black", glow = false, back = [], dataVersion = 4189 } = {}) => {
70	    const block = `${wood}_${wall ? "wall_" : ""}${hanging ? "hanging_" : ""}sign`;
71	    const state = wall ? { facing, waterlogged: "false" } : { rotation: String(rotation), waterlogged: "false", ...(hanging ? { attached: "false" } : {}) };
72	    const msg = (s) => t.string(dataVersion >= 4325 ? String(s ?? "") : JSON.stringify({ text: String(s ?? "") }));
73	    const side = (ls) => ({ messages: t.list("string", [0, 1, 2, 3].map((i) => msg(ls[i]).value)), color: t.string(color), has_glowing_text: t.byte(glow ? 1 : 0) });
74	    const nbt = t.compound({ id: t.string(hanging ? "minecraft:hanging_sign" : "minecraft:sign"), is_waxed: t.byte(0), front_text: t.compound(side(lines)), back_text: t.compound(side(back)) });
75	    return [block, state, nbt];
76	  },
77	};
78	const DYE_INDEX = ["white", "orange", "magenta", "light_blue", "yellow", "lime", "pink", "gray", "light_gray", "cyan", "purple", "blue", "brown", "green", "red", "black"];
79	const LEGACY_PATTERN = { base: "b", stripe_bottom: "bs", stripe_top: "ts", stripe_left: "ls", stripe_right: "rs", stripe_center: "cs", stripe_middle: "ms",
80	  stripe_downright: "drs", stripe_downleft: "dls", small_stripes: "ss", cross: "cr", straight_cross: "sc", diagonal_left: "ld", diagonal_right: "rud",
81	  half_vertical: "vh", half_horizontal: "hh", half_horizontal_bottom: "hhb", triangle_bottom: "bt", triangle_top: "tt", circle: "mc", rhombus: "mr",
82	  border: "bo", curly_border: "cbo", bricks: "bri", gradient: "gra", gradient_up: "gru", creeper: "cre", skull: "sku", flower: "flo", mojang: "moj", globe: "glb" };
83	
84	// ---- placement helpers ------------------------------------------------------------------------------------------
85	/** Call fn(pos, i) for count positions from `from`, `step` apart (the bay rhythm). */
86	export function tile(_g, { from = 0, step, count, to }, fn) {
87	  const n = count ?? Math.floor((to - from) / step) + 1;
88	  for (let i = 0; i < n; i++) fn(from + i * step, i);
89	}
90	
91	/** Run `paint(set)` twice: as written, and mirrored across x = cx (x' = 2cx - x), flipping east/west facings. */
92	export function mirrorX(g, cx, paint) {
93	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
94	  paint((x, y, z, block, state) => g.set(2 * cx - x, y, z, block, state && state.facing ? { ...state, facing: face.mirrorX(state.facing) } : state));
95	}
96	export function mirrorZ(g, cz, paint) {
97	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
98	  paint((x, y, z, block, state) => g.set(x, y, 2 * cz - z, block, state && state.facing ? { ...state, facing: face.mirrorZ(state.facing) } : state));
99	}
100	
101	/** Hollow box: walls (and optional floor/ceiling) of a cuboid. */
102	export function shell(g, a, b, block, { floor = true, ceiling = true, state } = {}) {
103	  const [x0, y0, z0] = a.map((v, i) => Math.min(v, b[i])), [x1, y1, z1] = a.map((v, i) => Math.max(v, b[i]));
104	  for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) {
105	    const edge = x === x0 || x === x1 || z === z0 || z === z1 || (floor && y === y0) || (ceiling && y === y1);
106	    if (edge) g.set(x, y, z, block, state);
107	  }
108	}
109	
110	/** Set a box to air (carving). Air is stored, so it clears the cell when the structure is placed. */
111	export const carve = (g, a, b) => g.fill(a, b, "minecraft:air");
112	
113	/** Replace only where the current block matches `from` (a name or a predicate). */
114	export function replace(g, a, b, from, block, state) {
115	  const match = typeof from === "function" ? from : (n) => n === ns(from);
116	  for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
117	    for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
118	      for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) if (match(g.blockAt(x, y, z))) g.set(x, y, z, block, state);
119	}
120	
121	/**
122	 * Wrap a grid so writes into protected cells are refused (counted, never thrown), so a decor script cannot
123	 * break function. protect: Set of "x,y,z" — default: the grid's own functional cells and the cells that must stay
124	 * clear around them (check.mjs functionalCells). `g.refused` lists what was blocked; report it.
125	 */
126	export function guard(g, protect) {
127	  const cells = protect ?? (() => { const f = functionalCells(g); return new Set([...f.protect.keys(), ...f.keepClear]); })();
128	  const refused = [];
129	  return new Proxy(g, {
130	    get(target, prop) {
131	      if (prop === "refused") return refused;
132	      if (prop === "protected") return cells;
133	      if (prop === "set") return (x, y, z, ...rest) => { if (cells.has(`${x},${y},${z}`)) { refused.push([x, y, z, rest[0]]); return target; } return target.set(x, y, z, ...rest); };
134	      if (prop === "fill") return (a, b, block, state) => { for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++) for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++) for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) { if (cells.has(`${x},${y},${z}`)) refused.push([x, y, z, block]); else target.set(x, y, z, block, state); } return target; };
135	      const v = Reflect.get(target, prop);
136	      return typeof v === "function" ? v.bind(target) : v;
137	    },
138	  });
139	}
140	
141	/**
142	 * Draw blocks from text, the way Litematica stores a schematic (a palette, then one index per cell): one character per
143	 * block, a legend for the characters. Far fewer tokens than a set() per block, and the layout is visible as written.
144	 *   layers(g, [x, y, z], { "#": "oak_planks", "b": ["red_bed", { facing: "south", part: "head" }], "c": "chest" }, [
145	 *     ["#####", "#b c#", "#b  #"],      // y: rows run along +x, successive rows along +z
146	 *     ["#####", "#   #", "#   #"],      // y + 1 ...
147	 *   ])
148	 * A single layer may be passed as one array of rows. Characters not in the legend (space, ".") are left as they are.
149	 * Writes go through g.set, so runParts' lock and palette report apply. Returns the number of blocks placed.
150	 */
151	export function layers(g, [x0, y0, z0], legend, rowsOrLayers) {
152	  const list = typeof rowsOrLayers[0] === "string" ? [rowsOrLayers] : rowsOrLayers;
153	  let n = 0;
154	  list.forEach((rows, dy) => rows.forEach((row, dz) => [...row].forEach((ch, dx) => {
155	    const e = legend[ch];
156	    if (e == null) return;
157	    const [block, state, nbt] = Array.isArray(e) ? e : [e];
158	    g.set(x0 + dx, y0 + dy, z0 + dz, block, state, nbt);
159	    n++;
160	  })));
161	  return n;
162	}
163	
164	/**
165	 * Run a build's parts in order so each part can only ADD to what earlier parts built: a write into a cell an earlier
166	 * part placed (air included, so no carving) is refused, counted, never thrown, so a later part can't knock holes in
167	 * a wall. Cells set before runParts (the ground) stay writable: farmland and paths may replace grass. With a palette
168	 * (palette.json, or its object: { roles: { role: [blocks] }, objects: [blocks] }), every block placed outside it is
169	 * reported. Prints one line per part, writes the reports to `report` (default parts-report.json; null for none) and
170	 * returns them.
171	 * roof: a roof spec (roof.json, as for `mcd roof --spec`) laid right after the FIRST part (the shell), so every later
172	 * part builds around the finished roof instead of the roof tool clearing the attic, gables and lofts after them. No
173	 * file yet (the roof part writes it, maybe in another copy at the same time): skipped with a note, never an error.
174	 * sockets.json in the working directory (or reserve: a layout or path; null for none) reserves the redstone shops'
175	 * envelopes: every write into one is refused. A part given { carve: true } (the stair joiner) may cut through earlier parts' floors and ceilings for its
176	 * stairwells: cells with air straight above or below. Walls stay refused.
177	 *   runParts(g, [["shell", shell.build], ["stairs", stairs.build, { carve: true }], ["garden", garden.build]],
178	 *     { palette: "palette.json", roof: "roof.json" })
179	 */
180	export function runParts(g, list, { palette, roof, reserve, log = console.log, report = "parts-report.json" } = {}) {
181	  // `mcd variant` rebuilds a finished build from its code with a roof change ($MCD_ROOF: JSON laid over roof.json)
182	  // and leaves the build's own reports alone ($MCD_PARTS_REPORT=none)
183	  if (process.env.MCD_PARTS_REPORT === "none") report = null;
184	  if (roof && process.env.MCD_ROOF) {
185	    const base = typeof roof === "string" ? (existsSync(roof) ? JSON.parse(readFileSync(roof, "utf8")) : null) : roof;
186	    if (base) roof = { ...base, ...JSON.parse(process.env.MCD_ROOF) };
187	  }
188	  const pal = typeof palette === "string" ? (existsSync(palette) ? JSON.parse(readFileSync(palette, "utf8")) : null) : palette;
189	  const allowed = pal ? new Set([...Object.values(pal.roles ?? {}).flat(), ...(pal.objects ?? [])].map(ns)) : null;
190	  const owned = new Set(), reports = [], cellsByPart = {};
191	  // redstone shop sockets (sockets.json, mcd sockets layout): their envelopes are reserved before any part runs, so a
192	  // write into one is refused like a write into an earlier part, and a carving part can't free them either
193	  const sock = reserve === undefined ? (existsSync("sockets.json") ? "sockets.json" : null) : reserve;
194	  const reserved = sock ? reservedCells(typeof sock === "string" ? JSON.parse(readFileSync(sock, "utf8")) : sock) : new Set();
195	  for (const k of reserved) owned.add(k);
196	  if (reserved.size) {
197	    // the fit-out the spec fixes (glass wall lines and back walls, a spawn-proof pit floor, the counters) is laid first
198	    // and locked like the envelopes: no part can swap a wall line's glass for a conductor
199	    const L = typeof sock === "string" ? JSON.parse(readFileSync(sock, "utf8")) : sock;
200	    // the ground laid before runParts (a site filled solid to the street) is dug out of the envelopes
201	    let dug = 0;
202	    for (const key of reserved) { const p = key.split(",").map(Number); if (g.inBounds(...p) && !/(^|:)(cave_)?air$/.test(g.blockAt(...p))) { g.set(...p, "air"); dug++; } }
203	    if (dug) log(`sockets: ${dug} cells of ground dug out of the envelopes`);
204	    const fit = socketFitout(L, L.fitout ?? {});
205	    for (const c of fit) { g.set(...c); owned.add(`${c[0]},${c[1]},${c[2]}`); }
206	    log(`sockets: ${reserved.size} cells reserved for the shops' redstone, ${fit.length} fit-out blocks laid (${typeof sock === "string" ? sock : "layout"})`);
207	  }
208	  for (const [name, build, opts0] of list) {
209	    // the stair joiner carves: a part given { carve: true }, or named for stairs (scaffolds rebuild the list their
210	    // own way, so the name is what survives)
211	    const opts = opts0 ?? (/stair/i.test(name) && !/^room:/i.test(name) ? { carve: true } : undefined);
212	    const mine = new Set(), refused = [], off = new Map(), carved = [];
213	    const airy = (target, x, y, z) => !target.inBounds(x, y, z) || /(^|:)(cave_)?air$/.test(target.blockAt(x, y, z));
214	    const write = (target, x, y, z, block, state, nbt) => {
215	      const k = `${x},${y},${z}`;
216	      // a carving part (the stair joiner) may cut through an earlier part's floors and ceilings: a cell with air
217	      // straight above or below it. Walls (solid above and below) stay refused.
218	      if (owned.has(k) && opts?.carve && !reserved.has(k) && (airy(target, x, y + 1, z) || airy(target, x, y - 1, z))) { owned.delete(k); carved.push([x, y, z]); }
219	      if (owned.has(k)) { refused.push([x, y, z, ns(block).replace("minecraft:", ""), target.blockAt(x, y, z).replace("minecraft:", "")]); return; }
220	      const b = ns(block);
221	      if (allowed && b !== "minecraft:air" && b !== "minecraft:cave_air" && !allowed.has(b)) off.set(b, (off.get(b) ?? 0) + 1);
222	      target.set(x, y, z, block, state, nbt);
223	      mine.add(k);
224	    };
225	    const view = new Proxy(g, {
226	      get(target, prop) {
227	        if (prop === "set") return (x, y, z, block, state, nbt) => { write(target, x, y, z, block, state, nbt); return view; };
228	        if (prop === "unset") return (x, y, z) => { write(target, x, y, z, "minecraft:air"); return view; };
229	        if (prop === "fill") return (a, b, block, state) => {
230	          for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
231	            for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
232	              for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) write(target, x, y, z, block, state);
233	          return view;
234	        };
235	        const v = Reflect.get(target, prop);
236	        return typeof v === "function" ? v.bind(target) : v;
237	      },
238	    });
239	    // in a variant (a roof change) a part written for the old roof may throw: keep what it placed, say so, go on
240	    if (process.env.MCD_ROOF) { try { build(view); } catch (e) { log(`part ${name}: FAILED with this roof (${String(e.message).split("\n")[0]}); kept what it placed`); } }
241	    else build(view);
242	    for (const k of mine) owned.add(k);
243	    if (process.env.MCD_PARTS_CELLS) cellsByPart[name] = [...mine].map((k) => { const c = g.get(...k.split(",").map(Number)); return [k, c ? c.block.replace("minecraft:", "") + (c.state ? JSON.stringify(c.state) : "") : "air"]; });
244	    const r = { part: name, placed: mine.size, refused: refused.length, refusedAt: refused.slice(0, 8), ...(carved.length ? { carved: carved.length } : {}),
245	      offPalette: [...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n}`) };
246	    reports.push(r);
247	    log(`part ${name}: ${r.placed} placed` + (carved.length ? ` (${carved.length} cut through earlier floors)` : "") +
248	      (r.refused ? `; REFUSED ${r.refused} writes into earlier parts (x,y,z wanted had: ${r.refusedAt.map((p) => `${p[0]},${p[1]},${p[2]} ${p[3]} ${p[4]}`).join("; ")})` : "") +
249	      (r.offPalette.length ? `; OFF-PALETTE: ${r.offPalette.join(", ")}` : ""));
250	    if (roof && reports.length === 1) r.offPalette.push(...layRoof(g, roof, owned, log, allowed));   // the shell's to fix
251	  }
252	  if (report) writeFileSync(report, JSON.stringify(reports, null, 1));
253	  // $MCD_PARTS_CELLS=<file>: every part's cells, for measuring how much code each block cost (lab token audits)
254	  if (process.env.MCD_PARTS_CELLS) writeFileSync(process.env.MCD_PARTS_CELLS, JSON.stringify(cellsByPart));
255	  return reports;
256	}
257	
258	// The roof from its spec on top of the shell, inside runParts: the cells it lays are locked like a part's; the shell
259	// cells it clears (above the eave) are freed for the parts that come after.
260	function layRoof(g, roof, owned, log, allowed) {
261	  const spec = typeof roof === "string" ? (existsSync(roof) ? JSON.parse(readFileSync(roof, "utf8")) : null) : roof;
262	  if (!spec) { log(`roof: skipped, no ${roof} yet (the roof part writes it); every later part builds without it`); return []; }
263	  const before = new Map([...g].map((c) => [c.pos.join(","), c.block + JSON.stringify(c.state ?? {})]));
264	  const r = reroof(g, { ...spec, keep: spec.keep ?? [] });
265	  if (r.shift?.some(Boolean)) throw new Error(`roof: the overhang grew the site and moved every block by ${r.shift}; make the site larger so the roof fits`);
266	  let laid = 0, freed = 0;
267	  const off = new Map();
268	  for (const c of g) {
269	    const k = c.pos.join(",");
270	    if (before.get(k) !== c.block + JSON.stringify(c.state ?? {})) {
271	      owned.add(k); laid++;
272	      if (allowed && !allowed.has(ns(c.block))) off.set(ns(c.block), (off.get(ns(c.block)) ?? 0) + 1);
273	    }
274	    before.delete(k);
275	  }
276	  for (const k of before.keys()) if (owned.delete(k)) freed++;                 // cleared by the roof: open for later parts
277	  log(`roof: ${laid} placed (${spec.preset ?? spec.style ?? "roof"}), ${freed} shell cells above the eave cleared${r.refused ? `, ${r.refused} kept` : ""}` +
278	    (off.size ? `; OFF-PALETTE: ${[...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n}`).join(", ")} (fix roof.json)` : ""));
279	  return [...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n} (roof.json)`);
280	}
