282	// ---- shape brushes (curved forms; massing) — the model picks parameters, code draws the form ---------------------
283	export * from "./shapes-curved.mjs";
284	export * from "./shapes-massing.mjs";
285	
286	// ---- landscaping brushes (terrain, strata, boulders, water, trees, paths, bridges) — see references/landscaping.md --
287	export * from "./terrain.mjs";
288	
289	// ---- roofs by style name (gable, hip, pyramid, mansard, gambrel, flat-parapet, shed, dutch-gable) — references/roofs.md
290	export * from "./roofs.mjs";
291	
292	// ---- facade brushes (signage, pilasters, surrounds, glazing, fixtures, planters) — references/detail-language.md -----
293	// Each is a function on a grid (writes only where it may: air for projections, plain wall for in-place trim; returns
294	// { cells, skipped, notes, info }) and a B.* twin that returns the plan as g.set argument lists, unchecked.
295	// at = a wall cell (bottom-left of the band / opening as seen from outside), face = the side it looks out of.
296	import { commitGrid, lookGrid, tuples } from "./brush-core.mjs";
297	import { plaquePlan, signboardPlan, buntingPlan } from "./brush-sign.mjs";
298	import { clockPlan } from "./brush-clock.mjs";
299	import { pilasterPlan } from "./brush-pilaster.mjs";
300	import { surroundPlan, glazingPlan } from "./brush-surround.mjs";
301	import { fixturePlan, planterPlan } from "./brush-fixture.mjs";
302	const withLook = (g, o) => ({ ...o, look: lookGrid(g), dataVersion: o?.dataVersion ?? g.dataVersion });
303	/** Lettering in a band: plaque(g, "LEAGUE HALL", { at, face, width, height, letter?, material?, frame?, style?, relief? }) */
304	export const plaque = (g, text, o) => commitGrid(g, plaquePlan(text, withLook(g, o)), o);
305	/** Redstone shop sockets: layoutSockets({ face, at, floorY, units: "DS DS", rows }) -> the layout (as sockets.json) */
306	export { layoutSockets };
307	/** The sockets' fit-out (glass wall lines and back walls, spawn-proof pit floor, counters): fitSockets(g, layout, { counter, glass }) */
308	export const fitSockets = (g, layout, o) => { const t = socketFitout(layout, o); for (const c of t) g.set(...c); return t.length; };
309	/** A clock face on a tower: clock(g, { center, face, radius?: 2-4, dial?, bezel?, hands?, time?: "10:10", out?: 0|1 }) */
310	export const clock = (g, o) => commitGrid(g, clockPlan(withLook(g, o)), o);
311	/** A shop sign: signboard(g, "BAKERY", { at, face, mode: "wall"|"hanging", width?, height?, wood? }) */
312	export const signboard = (g, text, o) => commitGrid(g, signboardPlan(text, withLook(g, o)), o);
313	/** Banners along a row: bunting(g, { from, to, face, colors?, every?, pattern? }) */
314	export const bunting = (g, o) => commitGrid(g, buntingPlan(withLook(g, o)), o);
315	/** A profiled pilaster: pilaster(g, { at, face, height, width?, out?, material?, profile?, shoulder? }) */
316	export const pilaster = (g, o) => commitGrid(g, pilasterPlan(o), o);
317	/** An opening surround: surround(g, { at, face, width, height, preset?, trim?, keystone?, reveal?, door?, arch? }) */
318	export const surround = (g, o) => commitGrid(g, surroundPlan(withLook(g, o)), o);
319	/** Glazing: glazing(g, { at, face, width, height, preset: grid|shopfront|transom|sidelights, frame?, door? }) */
320	export const glazing = (g, o) => commitGrid(g, glazingPlan(withLook(g, o)), o);
321	/** A light fitting: fixture(g, { at, face, mount: bracket|arm|top|hang, lamp? }) */
322	export const fixture = (g, o) => commitGrid(g, fixturePlan(withLook(g, o)), o);
323	/** A planter: planter(g, { at, face, width, kind: box|ground, depth?, plants? }) */
324	export const planter = (g, o) => commitGrid(g, planterPlan(withLook(g, o)), o);
325	Object.assign(B, {
326	  plaque: (text, o) => tuples(plaquePlan(text, o)), clock: (o) => tuples(clockPlan(o)), signboard: (text, o) => tuples(signboardPlan(text, o)), bunting: (o) => tuples(buntingPlan(o)),
327	  pilaster: (o) => tuples(pilasterPlan(o)), surround: (o) => tuples(surroundPlan(o)), glazing: (o) => tuples(glazingPlan(o)),
328	  fixture: (o) => tuples(fixturePlan(o)), planter: (o) => tuples(planterPlan(o)),
329	});
330	/** Run detail-language rules from code (weather / vary presets, treatments on every opening): returns { grid, report }. */
331	export { applyDetail as paint } from "./detail-lang.mjs";
